  .topbar-right {gap: var(--g-spacing-2);}
  .topbar-right > .g-avatar {display: none;}
  .page-heading p {font-size: 12px; line-height: 20px;}
  .page-heading {margin-bottom: var(--g-spacing-5);}
  .card-heading {padding: var(--g-spacing-5);}
  .card-heading p {font-size: 11px;}
