  .avatar-buttons {flex-wrap: wrap; gap: var(--g-spacing-1);}
  .avatar-controls p {line-height: 17px;}
  .avatar-check {display: none;}
  .large-avatar .g-avatar {--g-avatar-size: 52px;}
  .form-footer {align-items: stretch; flex-direction: column; padding: var(--g-spacing-5);}
  .footer-actions {justify-content: flex-end;}
  .save-hint {font-size: 10px;}
  .notification-description {font-size: 10px;}
  .privacy-note {align-items: flex-start; line-height: 17px; text-align: center;}
  .privacy-note svg {margin-top: 2px;}
  .page-footer {gap: var(--g-spacing-3); font-size: 9px;}
  .profile-card-dots {display: none;}
  .security-setting {padding: var(--g-spacing-3);}
  .security-copy label {font-size: 11px;}
}
@media (prefers-reduced-motion: reduce) {* {scroll-behavior: auto "'!important; transition: none !important;}}
